ALTER TABLE `gram`.`billing_meter_readings_by_time`
  MODIFY COMMENT 'Time-windowed usage ledger with optional FINAL convergence for logical-reading queries',
  ADD COLUMN `assistant_id` String MATERIALIZED attributes['assistant_id'] COMMENT 'Frozen reporting attribute for assistant identity.' AFTER `tokenizer_codec`,
  ADD COLUMN `billing_mode` LowCardinality(String) MATERIALIZED attributes['billing_mode'] COMMENT 'Frozen reporting attribute for billing mode.' AFTER `assistant_id`,
  ADD COLUMN `billing_user_cost_center_name` LowCardinality(String) MATERIALIZED attributes['billing_user_cost_center_name'] COMMENT 'Frozen reporting attribute for billing-user cost center.' AFTER `billing_mode`,
  ADD COLUMN `billing_user_department_name` LowCardinality(String) MATERIALIZED attributes['billing_user_department_name'] COMMENT 'Frozen reporting attribute for billing-user department.' AFTER `billing_user_cost_center_name`,
  ADD COLUMN `billing_user_directory_groups` LowCardinality(String) MATERIALIZED attributes['billing_user_directory_groups'] COMMENT 'Frozen JSON directory-group set for reporting.' AFTER `billing_user_department_name`,
  ADD COLUMN `billing_user_division_name` LowCardinality(String) MATERIALIZED attributes['billing_user_division_name'] COMMENT 'Frozen reporting attribute for billing-user division.' AFTER `billing_user_directory_groups`,
  ADD COLUMN `billing_user_employee_type` LowCardinality(String) MATERIALIZED attributes['billing_user_employee_type'] COMMENT 'Frozen reporting attribute for billing-user employee type.' AFTER `billing_user_division_name`,
  ADD COLUMN `billing_user_id` String MATERIALIZED attributes['billing_user_id'] COMMENT 'Frozen reporting identity of the billing user.' AFTER `billing_user_employee_type`,
  ADD COLUMN `billing_user_job_title` LowCardinality(String) MATERIALIZED attributes['billing_user_job_title'] COMMENT 'Frozen reporting attribute for billing-user job title.' AFTER `billing_user_id`,
  ADD COLUMN `mcp_server_id` String MATERIALIZED attributes['mcp_server_id'] COMMENT 'Frozen reporting identity of the MCP server.' AFTER `billing_user_job_title`,
  ADD COLUMN `mcp_server_slug` String MATERIALIZED attributes['mcp_server_slug'] COMMENT 'Frozen reporting label for the MCP server.' AFTER `mcp_server_id`,
  ADD COLUMN `mcp_server_type` LowCardinality(String) MATERIALIZED attributes['mcp_server_type'] COMMENT 'Frozen reporting namespace for the MCP server.' AFTER `mcp_server_slug`,
  ADD COLUMN `model` LowCardinality(String) MATERIALIZED attributes['model'] COMMENT 'Frozen reporting attribute for the model.' AFTER `mcp_server_type`,
  ADD COLUMN `provider` LowCardinality(String) MATERIALIZED attributes['provider'] COMMENT 'Frozen reporting attribute for the provider.' AFTER `model`,
  ADD COLUMN `risk_policy_id` String MATERIALIZED attributes['risk_policy_id'] COMMENT 'Frozen reporting attribute for risk-policy identity.' AFTER `provider`,
  ADD COLUMN `tool_name` LowCardinality(String) MATERIALIZED attributes['tool_name'] COMMENT 'Frozen reporting attribute for tool name.';
-- create "billing_meter_daily_summaries" table
CREATE TABLE `gram`.`billing_meter_daily_summaries` (
  `organization_id` String,
  `family` LowCardinality(String),
  `reading_kind` LowCardinality(String),
  `facet` LowCardinality(String),
  `day` Date,
  `series_kind` LowCardinality(String),
  `series_key` String,
  `label` String,
  `unit` LowCardinality(String),
  `measurement_method` LowCardinality(String),
  `quantity` Int128,
  `reading_count` Int64
) ENGINE = SummingMergeTree((quantity, reading_count))
PRIMARY KEY (`organization_id`, `family`, `reading_kind`, `facet`, `series_kind`, `series_key`, `day`) ORDER BY (`organization_id`, `family`, `reading_kind`, `facet`, `series_kind`, `series_key`, `day`, `unit`, `measurement_method`, `label`) PARTITION BY (toYYYYMM(day)) SETTINGS index_granularity = 8192 COMMENT 'Incremental daily meter family and facet marginals';
-- create "billing_meter_daily_summaries_mv" view
CREATE MATERIALIZED VIEW `gram`.`billing_meter_daily_summaries_mv` TO `gram`.`billing_meter_daily_summaries` AS SELECT organization_id, family, reading_kind, facet_identity.1 AS facet, toDate(occurred_at, 'UTC') AS day, facet_identity.2 AS series_kind, facet_identity.3 AS series_key, max(facet_label) AS label, unit, measurement_method, sum(toInt128(value)) AS quantity, toInt64(count()) AS reading_count FROM (SELECT organization_id, reading_kind, occurred_at, unit, measurement_method, value, multiIf(meter_id = 'gram.agent_session.storage', 'agent_session_storage', (meter_id IN ('gram.mcp.bandwidth.ingress', 'gram.mcp.bandwidth.egress')), 'mcp_bandwidth', 'risk_content_scans') AS family, arrayJoin(multiIf(meter_id = 'gram.agent_session.storage', [tuple('total', 'value', 'total', 'Total'), tuple('project', 'value', toString(project_id), toString(project_id)), tuple('model', if(model = '', 'unset', 'value'), model, if(model = '', '(unset)', model)), tuple('provider', if(provider = '', 'unset', 'value'), provider, if(provider = '', '(unset)', provider)), tuple('billing_mode', if(billing_mode = '', 'unset', 'value'), billing_mode, if(billing_mode = '', '(unset)', billing_mode)), tuple('assistant', if(assistant_id = '', 'unset', 'value'), assistant_id, if(assistant_id = '', '(unset)', assistant_id)), tuple('billing_user', if(billing_user_id = '', 'unset', 'value'), billing_user_id, if(billing_user_id = '', '(unset)', billing_user_id)), tuple('division', if(billing_user_division_name = '', 'unset', 'value'), billing_user_division_name, if(billing_user_division_name = '', '(unset)', billing_user_division_name)), tuple('department', if(billing_user_department_name = '', 'unset', 'value'), billing_user_department_name, if(billing_user_department_name = '', '(unset)', billing_user_department_name)), tuple('job_title', if(billing_user_job_title = '', 'unset', 'value'), billing_user_job_title, if(billing_user_job_title = '', '(unset)', billing_user_job_title)), tuple('employee_type', if(billing_user_employee_type = '', 'unset', 'value'), billing_user_employee_type, if(billing_user_employee_type = '', '(unset)', billing_user_employee_type)), tuple('cost_center', if(billing_user_cost_center_name = '', 'unset', 'value'), billing_user_cost_center_name, if(billing_user_cost_center_name = '', '(unset)', billing_user_cost_center_name)), tuple('directory_group_set', if(empty(arraySort(arrayDistinct(JSONExtract(if(billing_user_directory_groups = '', '[]', billing_user_directory_groups), 'Array(String)')))), 'unset', 'value'), if(empty(arraySort(arrayDistinct(JSONExtract(if(billing_user_directory_groups = '', '[]', billing_user_directory_groups), 'Array(String)')))), '', toJSONString(arraySort(arrayDistinct(JSONExtract(if(billing_user_directory_groups = '', '[]', billing_user_directory_groups), 'Array(String)'))))), if(empty(arraySort(arrayDistinct(JSONExtract(if(billing_user_directory_groups = '', '[]', billing_user_directory_groups), 'Array(String)')))), '(unset)', arrayStringConcat(arraySort(arrayDistinct(JSONExtract(if(billing_user_directory_groups = '', '[]', billing_user_directory_groups), 'Array(String)'))), ', ')))], (meter_id IN ('gram.mcp.bandwidth.ingress', 'gram.mcp.bandwidth.egress')), [tuple('total', 'value', 'total', 'Total'), tuple('project', 'value', toString(project_id), toString(project_id)), tuple('direction', 'value', if(meter_id = 'gram.mcp.bandwidth.ingress', 'ingress', 'egress'), if(meter_id = 'gram.mcp.bandwidth.ingress', 'Ingress', 'Egress')), tuple('mcp_server', if((mcp_server_type = '') OR (mcp_server_id = ''), 'unset', 'value'), if((mcp_server_type = '') OR (mcp_server_id = ''), '', concat(mcp_server_type, ':', mcp_server_id)), if((mcp_server_type = '') OR (mcp_server_id = ''), '(unset)', if(mcp_server_slug = '', concat(mcp_server_type, ':', mcp_server_id), mcp_server_slug))), tuple('server_type', if(mcp_server_type = '', 'unset', 'value'), mcp_server_type, if(mcp_server_type = '', '(unset)', mcp_server_type))], [tuple('total', 'value', 'total', 'Total'), tuple('project', 'value', toString(project_id), toString(project_id)), tuple('scanner', 'value', meter_id, multiIf(meter_id = 'gram.risk.scan.gitleaks', 'Gitleaks', meter_id = 'gram.risk.scan.presidio', 'Presidio', meter_id = 'gram.risk.scan.prompt_injection', 'Prompt injection', meter_id = 'gram.risk.scan.prompt_policy', 'Prompt policy', meter_id = 'gram.risk.scan.custom_rules', 'Custom rules', 'CLI destructive')), tuple('policy', if(risk_policy_id = '', 'unset', 'value'), risk_policy_id, if(risk_policy_id = '', '(unset)', risk_policy_id)), tuple('judge_model', if(model = '', 'unset', 'value'), model, if(model = '', '(unset)', model)), tuple('judge_provider', if(provider = '', 'unset', 'value'), provider, if(provider = '', '(unset)', provider)), tuple('tool_name', if(tool_name = '', 'unset', 'value'), tool_name, if(tool_name = '', '(unset)', tool_name))])) AS facet_identity, facet_identity.4 AS facet_label FROM gram.billing_meter_readings_by_time WHERE meter_id IN ('gram.agent_session.storage', 'gram.mcp.bandwidth.ingress', 'gram.mcp.bandwidth.egress', 'gram.risk.scan.gitleaks', 'gram.risk.scan.presidio', 'gram.risk.scan.prompt_injection', 'gram.risk.scan.prompt_policy', 'gram.risk.scan.custom_rules', 'gram.risk.scan.cli_destructive')) GROUP BY organization_id, family, reading_kind, facet, day, series_kind, series_key, unit, measurement_method;
